<?php session_start();?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lavash N1 • Kuryer Pro</title><style>*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui;background:linear-gradient(180deg,#fff7f1,#f6f7fb);color:#101828}.wrap{max-width:1100px;margin:auto;padding:18px}.hero{padding:24px;border-radius:26px;background:linear-gradient(135deg,#111827,#293548);color:#fff;box-shadow:0 25px 70px #10182822}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:14px 0}.card,.order{background:#fff;border:1px solid #e4e7ec;border-radius:20px;padding:17px;box-shadow:0 16px 45px #1018280d}.metric{font-size:25px;font-weight:1000;margin-top:4px}.order{margin:12px 0}.muted{color:#667085}.pill{display:inline-block;padding:6px 10px;border-radius:999px;background:#dcfce7;font-weight:900;font-size:12px}.btn{display:inline-block;border:0;border-radius:13px;padding:11px 14px;margin:4px 4px 0 0;background:linear-gradient(135deg,#ff4d00,#ff8a00);color:#fff;text-decoration:none;font-weight:900;cursor:pointer}.dark{background:#111827}.map{margin-top:8px;border:1px solid #eaecf0;border-radius:14px;overflow:hidden}.map iframe{width:100%;height:190px;border:0;display:block}.history{max-height:520px;overflow:auto}.login{max-width:430px;margin:70px auto}.login input{width:100%;padding:12px;margin:7px 0;border:1px solid #d0d5dd;border-radius:13px;font:inherit}.login button{width:100%}.error{color:#b42318;background:#fef3f2;border:1px solid #fecdca;padding:11px;border-radius:12px}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.wrap{padding:12px}.grid{grid-template-columns:1fr 1fr}.hero h1{font-size:23px}}</style></head><body><div class="wrap"><div class="hero"><div style="font-size:38px">🛵</div><h1>Lavash N1 • Kuryer Pro</h1><p>Buyurtma, xarita, yo‘l va kunlik yetkazib berish statistikasi.</p></div><div id="app" style="margin-top:14px">Tekshirilmoqda...</div></div><script>
const app=document.getElementById('app'),TOKEN_KEY='lavash_n1_courier_token';
async function api(action,options={}){const token=localStorage.getItem(TOKEN_KEY);const join=action.includes('?')?'&':'?';const tokenParam=token?'&token='+encodeURIComponent(token):'';const headers=new Headers(options.headers||{});if(token)headers.set('X-Courier-Token',token);const r=await fetch('courier_api.php?action='+encodeURIComponent(action)+join+'_t='+Date.now()+tokenParam,{cache:'no-store',credentials:'same-origin',...options,headers});const text=await r.text();let d;try{d=JSON.parse(text)}catch(e){throw new Error('Server JSON javob bermadi (HTTP '+r.status+')')};if(r.status===401){localStorage.removeItem(TOKEN_KEY)}return d}
const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function map(x){const lat=Number(x.lat),lng=Number(x.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng)||!lat||!lng)return '<p class="muted">📍 Mijoz lokatsiyasi tasdiqlanmagan.</p>';const q=encodeURIComponent(lat+','+lng);return '<div class="map"><iframe loading="lazy" src="https://maps.google.com/maps?q='+q+'&z=16&output=embed"></iframe></div><a class="btn dark" target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+q+'">🧭 Google Maps’da yo‘l</a>'}
async function boot(){try{const m=await api('me');if(!m.ok){showLogin(m.message||'');return}await render(m.data)}catch(e){showLogin(e.message)}}
function showLogin(message=''){app.innerHTML='<div class="card login"><h2>🔐 Kuryer kirishi</h2><p class="muted">URL orqali kirish.</p><input id="login" placeholder="Login: Daler" autocomplete="username"><input id="pass" type="password" placeholder="Parol: Lavash" autocomplete="current-password"><button class="btn" onclick="goLogin()">Kirish</button><p id="err" class="error" style="display:'+(message?'block':'none')+'">'+esc(message)+'</p></div>'}
async function goLogin(){const err=document.getElementById('err');err.style.display='none';try{const f=new FormData();f.append('login',document.getElementById('login').value);f.append('password',document.getElementById('pass').value);const d=await api('login',{method:'POST',body:f});if(d.ok&&d.token){localStorage.setItem(TOKEN_KEY,d.token);await render(d.data);return}err.textContent=d.message||'Login xatosi';err.style.display='block'}catch(e){err.textContent=e.message;err.style.display='block'}}
async function render(me){try{const [s,h,o]=await Promise.all([api('summary'),api('history'),api('orders')]);if(!s.ok||!h.ok||!o.ok){if([s,h,o].some(x=>x&&x.message==='Kirish kerak.')){localStorage.removeItem(TOKEN_KEY);showLogin('Sessiya tugagan. Qayta kiring.');return}throw new Error((!s.ok&&s.message)||(!h.ok&&h.message)||(!o.ok&&o.message)||'API xatosi')}const d=s.data||{},active=o.data||[],hist=h.data||[];app.innerHTML='<div class="grid"><div class="card">👤<div class="metric">'+esc(me.name)+'</div><span class="pill">ONLINE</span></div><div class="card">📦 Faol<div class="metric">'+active.length+'</div></div><div class="card">💰 Bugungi savdo<div class="metric">'+Number(d.sales||0).toLocaleString('uz-UZ')+' so‘m</div><div class="muted">06:00–00:00</div></div><div class="card">✅ Yetkazilgan<div class="metric">'+(d.completed||0)+'</div></div></div><div class="card"><button class="btn dark" onclick="logout()">Chiqish</button><h2>🛵 Faol buyurtmalar</h2><div id="active">'+(active.map(x=>'<div class="order"><b>#'+x.id+' — '+esc(x.customer_name)+'</b><p>📞 '+esc(x.phone||'')+'<br>📍 '+esc(x.address||'')+'<br>💰 '+Number(x.amount).toLocaleString('uz-UZ')+' so‘m · '+((x.payment_method||'cash')==='card'?'💳 Karta':'💵 Naqd')+'</p>'+map(x)+'<p class="muted">'+esc(x.note||'')+'</p><button class="btn" onclick="st('+x.id+',\'delivering\')">🛵 Yo‘lda</button><button class="btn" onclick="st('+x.id+',\'completed\')">✅ Yetkazildi</button></div>').join('')||'<p class="muted">Faol buyurtma yo‘q.</p>')+'</div></div><div class="card" style="margin-top:14px"><h2>🧾 Buyurtma tarixi</h2><div class="history">'+(hist.map(x=>'<div class="order"><b>#'+x.id+' '+esc(x.customer_name)+'</b><br><span class="muted">'+new Date(x.created_at).toLocaleString('uz-UZ')+' · '+esc(x.status)+'</span><br>'+Number(x.amount).toLocaleString('uz-UZ')+' so‘m · '+((x.payment_method||'cash')==='card'?'Karta':'Naqd')+'</div>').join('')||'<p class="muted">Tarix yo‘q.</p>')+'</div></div>'}catch(e){app.innerHTML='<div class="card error"><b>Kuryer ma’lumotlarini yuklab bo‘lmadi.</b><br>'+esc(e.message)+'<br><br><button class="btn" onclick="location.reload()">↻ Qayta yuklash</button></div>'}}
async function st(id,status){try{const f=new FormData();f.append('order_id',id);f.append('status',status);const d=await api('status',{method:'POST',body:f});if(!d.ok)throw new Error(d.message||'Status saqlanmadi');const m=await api('me');if(m.ok)await render(m.data)}catch(e){alert(e.message)}}
async function logout(){try{await api('logout')}finally{localStorage.removeItem(TOKEN_KEY);location.reload()}}
boot();setInterval(async()=>{if(!localStorage.getItem(TOKEN_KEY))return;try{const m=await api('me');if(m.ok)await render(m.data)}catch(e){}},10000);
</script></body></html>